import fs from 'node:fs';
import playwright from 'playwright-core';
const {chromium}=playwright;

const candidates=[process.env.CHROME_PATH,'/usr/bin/google-chrome','/usr/bin/google-chrome-stable','/usr/bin/chromium','/usr/bin/chromium-browser'].filter(Boolean);
const executablePath=candidates.find(path=>fs.existsSync(path));
if(!executablePath)throw new Error('No Chrome/Chromium executable found on runner');
const browser=await chromium.launch({headless:true,executablePath,args:['--no-sandbox','--autoplay-policy=no-user-gesture-required']});
const page=await browser.newPage({viewport:{width:1280,height:900},locale:'ko-KR'});
const errors=[];page.on('pageerror',error=>errors.push(String(error)));
await page.route('**/api/visitors',route=>route.fulfill({status:200,contentType:'application/json',body:'{"available":false}'}));
await page.goto('http://127.0.0.1:4173/player/',{waitUntil:'networkidle'});
await page.waitForFunction(()=>window.LullabyTrainJourney&&window.LullabyJourneyRuntime);
await page.waitForFunction(()=>document.querySelector('.journey-visual-layer.active')?.dataset.journey==='passenger_aircraft_cabin');
await page.waitForFunction(()=>window.LullabyJourneyBackground&&document.querySelector('[data-journey-background-toggle]')&&document.querySelector('[data-journey-display-button]'));
let stageState=await page.evaluate(()=>({count:document.querySelectorAll('#journeyStageBar [data-stage-index]').length,active:document.querySelector('#journeyStageBar [aria-current="step"]')?.dataset.stageIndex,selectOptions:document.querySelectorAll('#journeyStageSelect option').length}));
if(stageState.count!==9||stageState.active!=='0'||stageState.selectOptions!==9)throw new Error(`Aircraft stage control missing: ${JSON.stringify(stageState)}`);
let eventToggle=await page.evaluate(()=>({checked:document.getElementById('journeyEventToggle')?.getAttribute('aria-checked'),label:document.querySelector('[data-journey-event-label]')?.textContent}));
if(eventToggle.checked!=='true'||eventToggle.label!=='랜덤 이벤트')throw new Error(`Journey random-event toggle missing: ${JSON.stringify(eventToggle)}`);
await page.locator('#journeyEventToggle').click();
eventToggle=await page.evaluate(()=>({enabled:window.LullabyJourneyEvents.enabled,checked:document.getElementById('journeyEventToggle')?.getAttribute('aria-checked'),event:document.getElementById('eventLabel')?.textContent}));
if(eventToggle.enabled||eventToggle.checked!=='false'||eventToggle.event!=='꺼짐')throw new Error(`Journey random-event toggle did not disable: ${JSON.stringify(eventToggle)}`);
await page.locator('#journeyEventToggle').click();
const aircraftProfiles=await page.evaluate(()=>[0,.025,.05625,.9125,.9854167].map(ratio=>window.LullabyJourneyStageControl.transitionProfileAt(window.LullabyJourneyRuntime.totalMs*ratio)));
if(new Set(aircraftProfiles.map(profile=>profile.gainSeconds)).size<4||aircraftProfiles[2].gainSeconds<=aircraftProfiles[1].gainSeconds)throw new Error(`Aircraft transitions are not phase-specific: ${JSON.stringify(aircraftProfiles)}`);
let backgroundState=await page.evaluate(()=>({position:getComputedStyle(document.querySelector('.journey-visual')).position,top:document.querySelector('.journey-visual').getBoundingClientRect().top,ambient:window.LullabyJourneyBackground.ambientEnabled}));
if(backgroundState.position!=='fixed'||backgroundState.top!==0)throw new Error(`Journey background is not viewport-fixed: ${JSON.stringify(backgroundState)}`);
await page.locator('[data-journey-background-toggle]').click();
backgroundState=await page.evaluate(()=>({off:document.body.classList.contains('journey-ambient-off'),ambient:window.LullabyJourneyBackground.ambientEnabled}));
if(!backgroundState.off||backgroundState.ambient)throw new Error(`Journey background toggle did not switch off: ${JSON.stringify(backgroundState)}`);
await page.locator('[data-journey-background-toggle]').click();
await page.evaluate(()=>scrollTo(0,600));
backgroundState=await page.evaluate(()=>({off:document.body.classList.contains('journey-ambient-off'),top:document.querySelector('.journey-visual').getBoundingClientRect().top}));
if(backgroundState.off||backgroundState.top!==0)throw new Error(`Journey background moved while scrolling: ${JSON.stringify(backgroundState)}`);
await page.evaluate(()=>scrollTo(0,0));
await page.locator('[data-journey-display-button]').first().click();
backgroundState=await page.evaluate(()=>({mode:document.body.classList.contains('journey-display-mode'),exit:document.querySelector('.journey-display-exit button')?.textContent}));
if(!backgroundState.mode||!backgroundState.exit)throw new Error(`Journey display mode did not open: ${JSON.stringify(backgroundState)}`);
await page.locator('.journey-display-exit button').click();
const journeyOrder=await page.locator('#journeySelector [data-journey]').evaluateAll(nodes=>nodes.map(node=>node.dataset.journey));
if(journeyOrder[2]!=='spacecraft_journey')throw new Error(`Spacecraft is not the third Journey: ${JSON.stringify(journeyOrder)}`);
await page.locator('[data-journey="train_journey"]').click();
let state=await page.evaluate(()=>({active:window.LullabyTrainJourney.active,title:document.querySelector('.aircraft-title-row h3')?.textContent,phase:document.querySelector('#phaseLabel')?.textContent}));
if(!state.active||!state.title?.includes('열차')||!['Ready','준비'].includes(state.phase))throw new Error(`Train selection failed: ${JSON.stringify(state)}`);
stageState=await page.evaluate(()=>({count:document.querySelectorAll('#journeyStageBar [data-stage-index]').length,labels:[...document.querySelectorAll('#journeyStageBar b')].map(node=>node.textContent)}));
if(stageState.count!==5||stageState.labels[2]!=='야간 운행')throw new Error(`Train stage bar did not update: ${JSON.stringify(stageState)}`);
const trainProfiles=await page.evaluate(()=>window.LullabyTrainJourney.stagePoints(window.LullabyJourneyRuntime.totalMs).map(point=>window.LullabyTrainJourney.transitionProfile(point.ms,window.LullabyJourneyRuntime.totalMs)));
if(new Set(trainProfiles.map(profile=>profile.filterSeconds)).size<4||trainProfiles[2].filterSeconds<=trainProfiles[0].filterSeconds)throw new Error(`Train transitions are not phase-specific: ${JSON.stringify(trainProfiles)}`);
await page.waitForTimeout(1100);
state=await page.evaluate(()=>({title:document.querySelector('.aircraft-title-row h3')?.textContent,phase:document.querySelector('#phaseLabel')?.textContent}));
if(!state.title?.includes('열차')||!['Ready','준비'].includes(state.phase))throw new Error(`Train selection was overwritten by localization: ${JSON.stringify(state)}`);
await page.locator('#scenePlay').click();await page.waitForTimeout(700);
state=await page.evaluate(()=>({phase:document.querySelector('#phaseLabel')?.textContent,role:window.LullabyTrainJourney.audibleRole,playing:document.querySelector('#scenePlay')?.textContent}));
if(state.phase!=='Departing'||state.role!=='departure'||!state.playing.includes('Ⅱ'))throw new Error(`Train departure failed: ${JSON.stringify(state)}`);
await page.waitForTimeout(1100);
state=await page.evaluate(()=>({phase:document.querySelector('#phaseLabel')?.textContent,title:document.querySelector('.aircraft-title-row h3')?.textContent}));
if(['Ready','준비'].includes(state.phase)||!state.title?.includes('열차'))throw new Error(`Train playback was overwritten by localization: ${JSON.stringify(state)}`);
await page.evaluate(()=>window.LullabyJourneyRuntime.seekToMs(31183));await page.waitForTimeout(700);
state=await page.evaluate(()=>({phase:document.querySelector('#phaseLabel')?.textContent,role:window.LullabyTrainJourney.audibleRole}));
if(state.phase!=='Departing'||state.role!=='bed')throw new Error(`Train bed did not pre-roll before the phase boundary: ${JSON.stringify(state)}`);
await page.locator('#journeyNextPhase').click();await page.waitForTimeout(700);
state=await page.evaluate(()=>({phase:document.querySelector('#phaseLabel')?.textContent,role:window.LullabyTrainJourney.audibleRole,elapsed:window.LullabyJourneyRuntime.elapsedMs}));
if(state.phase!=='Leaving city'||state.role!=='bed'||state.elapsed<35000)throw new Error(`Train bed transition failed: ${JSON.stringify(state)}`);
await page.evaluate(()=>window.LullabyJourneyRuntime.seekToMs(window.LullabyJourneyRuntime.totalMs-32000));await page.waitForTimeout(700);
state=await page.evaluate(()=>({phase:document.querySelector('#phaseLabel')?.textContent,role:window.LullabyTrainJourney.audibleRole}));
if(state.phase!=='Arriving'||state.role!=='arrival')throw new Error(`Train arrival transition failed: ${JSON.stringify(state)}`);
await page.locator('#scenePlay').click();await page.locator('button[data-journey="passenger_aircraft_cabin"]').click();
if(await page.locator('.aircraft-title-row h3').textContent()!=='Passenger Aircraft Cabin')throw new Error('Aircraft selector did not restore the original journey');

for(const journey of[
  ['ferry_journey','야간 페리 여정',128667],
  ['spacecraft_journey','우주선 표류',17824],
  ['submarine_journey','잠수함 항해',47282]
]){
  const[id,title,departureMs]=journey;
  const immediate=await page.evaluate(id=>{document.querySelector(`button[data-journey="${id}"]`)?.click();return{title:document.querySelector('.aircraft-title-row h3')?.textContent,phase:document.querySelector('#phaseLabel')?.textContent}},id);
  if(immediate.title!==title||!['Ready','준비'].includes(immediate.phase))throw new Error(`${id} flickered through the aircraft renderer: ${JSON.stringify(immediate)}`);
  await page.waitForTimeout(80);
  state=await page.evaluate(()=>({active:window.LullabyRemainingJourneys?.active,title:document.querySelector('.aircraft-title-row h3')?.textContent,phase:document.querySelector('#phaseLabel')?.textContent,background:document.querySelector('.journey-visual-layer.active')?.dataset.journey,backgroundCount:document.querySelectorAll('.journey-visual-layer.active').length}));
  if(state.active!==id||state.title!==title||!['Ready','준비'].includes(state.phase)||state.background!==id||state.backgroundCount!==1)throw new Error(`${id} selection failed: ${JSON.stringify(state)}`);
  const profiles=await page.evaluate(()=>{const runtime=window.LullabyRemainingJourneys,total=window.LullabyJourneyRuntime.totalMs,cfg=runtime.configs[runtime.active];return runtime.stagePoints(total,cfg).map(point=>runtime.transitionProfile(point.ms,total,cfg))});
  if(new Set(profiles.map(profile=>profile.gainSeconds)).size<4||profiles[2].gainSeconds<=profiles[0].gainSeconds)throw new Error(`${id} transitions are not phase-specific: ${JSON.stringify(profiles)}`);
  await page.waitForTimeout(1100);
  state=await page.evaluate(()=>({title:document.querySelector('.aircraft-title-row h3')?.textContent,phase:document.querySelector('#phaseLabel')?.textContent}));
  if(state.title!==title||!['Ready','준비'].includes(state.phase))throw new Error(`${id} selection was overwritten by localization: ${JSON.stringify(state)}`);
  await page.locator('#scenePlay').click();await page.waitForTimeout(650);
  state=await page.evaluate(()=>({role:window.LullabyRemainingJourneys?.audibleRole,playing:document.querySelector('#scenePlay')?.textContent,eventUrl:window.LullabyRemainingJourneys?.configs?.[window.LullabyRemainingJourneys.active]?.event?.url,eventReady:Boolean(window.LullabyRemainingJourneys?.eventNode)}));
  if(state.role!=='departure'||!state.playing.includes('Ⅱ')||!state.eventUrl||!state.eventReady)throw new Error(`${id} departure/event setup failed: ${JSON.stringify(state)}`);
  await page.locator('#journeyEventToggle').click();await page.waitForTimeout(60);
  state=await page.evaluate(()=>({enabled:window.LullabyJourneyEvents.enabled,event:document.getElementById('eventLabel')?.textContent,eventPaused:window.LullabyRemainingJourneys?.eventNode?.el.paused}));
  if(state.enabled||state.event!=='꺼짐'||!state.eventPaused)throw new Error(`${id} random event did not stop when disabled: ${JSON.stringify(state)}`);
  await page.locator('#journeyEventToggle').click();
  await page.waitForTimeout(1100);
  state=await page.evaluate(()=>({phase:document.querySelector('#phaseLabel')?.textContent,title:document.querySelector('.aircraft-title-row h3')?.textContent}));
  if(['Ready','준비'].includes(state.phase)||state.title!==title)throw new Error(`${id} playback was overwritten by localization: ${JSON.stringify(state)}`);
  await page.evaluate(ms=>window.LullabyJourneyRuntime.seekToMs(ms-4000),departureMs);await page.waitForTimeout(650);
  state=await page.evaluate(()=>({role:window.LullabyRemainingJourneys?.audibleRole}));
  if(state.role!=='bed')throw new Error(`${id} bed did not pre-roll before the phase boundary: ${JSON.stringify(state)}`);
  await page.locator('#journeyNextPhase').click();await page.waitForTimeout(650);
  state=await page.evaluate(()=>({role:window.LullabyRemainingJourneys?.audibleRole,elapsed:window.LullabyJourneyRuntime.elapsedMs}));
  if(state.role!=='bed'||state.elapsed<departureMs-1000)throw new Error(`${id} bed transition failed: ${JSON.stringify(state)}`);
  const bedBefore=await page.evaluate(()=>{const runtime=window.LullabyRemainingJourneys,key=runtime.configs[runtime.active].roles.bed[0];return runtime.activeNodes[key].el.currentTime});
  await page.locator('#journeyStageBar [data-stage-index="2"]').click();
  if(!await page.evaluate(()=>document.body.classList.contains('journey-phase-transition')))throw new Error(`${id} stage transition feedback missing`);
  await page.waitForTimeout(700);
  const bedAfter=await page.evaluate(()=>{const runtime=window.LullabyRemainingJourneys,key=runtime.configs[runtime.active].roles.bed[0];return{time:runtime.activeNodes[key].el.currentTime,elapsed:window.LullabyJourneyRuntime.elapsedMs,stage:document.querySelector('#journeyStageBar [aria-current="step"]')?.dataset.stageIndex}});
  if(Math.abs(bedAfter.time-bedBefore)>3||bedAfter.stage!=='2')throw new Error(`${id} same-bed stage transition restarted audio: ${JSON.stringify({bedBefore,bedAfter})}`);
  await page.evaluate(()=>window.LullabyJourneyRuntime.seekToMs(window.LullabyJourneyRuntime.totalMs-1000));await page.waitForTimeout(650);
  state=await page.evaluate(()=>{const runtime=window.LullabyRemainingJourneys,paused=Object.fromEntries(Object.entries(runtime?.activeNodes||{}).map(([key,node])=>[key,node.el.paused]));return{role:runtime?.audibleRole,paused,bedOverlaps:runtime?.configs?.[runtime.active]?.roles?.bed?.every(key=>paused[key]===false)}});
  if(state.role!=='arrival'||!state.bedOverlaps)throw new Error(`${id} arrival crossfade failed: ${JSON.stringify(state)}`);
  await page.locator('#scenePlay').click();await page.waitForTimeout(60);
}
await page.locator('button[data-journey="passenger_aircraft_cabin"]').click();
if(errors.length)throw new Error(`browser errors: ${errors.join(' | ')}`);
const mobile=await browser.newPage({viewport:{width:390,height:844},locale:'ko-KR'});
await mobile.goto('http://127.0.0.1:4173/player/',{waitUntil:'networkidle'});
await mobile.waitForFunction(()=>document.querySelector('.android-top-actions [data-journey-display-placement="mobile"]'));
const mobileStages=await mobile.evaluate(()=>({bar:getComputedStyle(document.getElementById('journeyStageBar')).display,select:getComputedStyle(document.querySelector('.journey-stage-select')).display,options:document.querySelectorAll('#journeyStageSelect option').length}));
if(mobileStages.bar!=='none'||mobileStages.select==='none'||mobileStages.options!==9)throw new Error(`Mobile stage dropdown failed: ${JSON.stringify(mobileStages)}`);
await mobile.locator('[data-journey-display-placement="mobile"]').click();
await mobile.waitForTimeout(500);
const mobileDisplay=await mobile.evaluate(()=>{
  const visual=document.querySelector('.journey-visual'),layer=document.querySelector('.journey-visual-layer.active'),button=document.querySelector('[data-journey-display-placement="mobile"]');
  const visualStyle=getComputedStyle(visual),rect=visual?.getBoundingClientRect();
  return{mode:document.body.classList.contains('journey-display-mode'),fallback:document.body.classList.contains('journey-display-landscape-fallback'),buttonParent:button?.parentElement?.className,canvasWidth:Math.round(parseFloat(visualStyle.width)||0),canvasHeight:Math.round(parseFloat(visualStyle.height)||0),rectWidth:Math.round(rect?.width||0),rectHeight:Math.round(rect?.height||0),fit:getComputedStyle(layer).objectFit};
});
if(!mobileDisplay.mode||!mobileDisplay.fallback||mobileDisplay.buttonParent!=='android-top-actions'||mobileDisplay.canvasWidth!==844||mobileDisplay.canvasHeight!==390||mobileDisplay.rectWidth!==390||mobileDisplay.rectHeight!==844||mobileDisplay.fit!=='contain')throw new Error(`Mobile landscape scene display failed: ${JSON.stringify(mobileDisplay)}`);
await mobile.close();await browser.close();console.log('Web Aircraft, Train, Ferry, Spacecraft and Submarine journey routing passed');
